const item = $input.first().json || {};
if (item.demo_mode === true) {
  return [{ json: { demo_mode: true } }];
}
const rawText = String(item.text || '');
if (!rawText.trim()) {
  throw new Error('Empty PDF invoice text extracted. Ensure the email attachment is a searchable PDF (or enable OCR before 3-way match).');
}
const invMatch =
  rawText.match(/(?:INVOICE|INV)[ \t]*(?:#|NO\.?|NUMBER)[ \t]*[:\-]?[ \t]*([A-Z0-9][A-Z0-9/_-]{1,})/i) ||
  rawText.match(/(?:INVOICE|INV)[ \t]*[:#][ \t]*([A-Z0-9][A-Z0-9/_-]{1,})/i);
const poMatch =
  rawText.match(/(?:PO|PURCHASE[ \t]+ORDER)[ \t]*(?:#|NO\.?|NUMBER)[ \t]*[:\-]?[ \t]*([A-Z0-9][A-Z0-9/_-]{1,})/i) ||
  rawText.match(/(?:PO|PURCHASE[ \t]+ORDER)[ \t]*[:#][ \t]*([A-Z0-9][A-Z0-9/_-]{1,})/i);
const vendorMatch = rawText.match(/(?:Vendor|Supplier|From)[ \t]*:[ \t]*([^\r\n]+)/i);
const invDateMatch = rawText.match(/(?:Invoice[ \t]+Date|Date)[ \t]*:[ \t]*([0-9]{4}-[0-9]{2}-[0-9]{2})/i);
const dueDateMatch = rawText.match(/Due[ \t]+Date[ \t]*:[ \t]*([0-9]{4}-[0-9]{2}-[0-9]{2})/i);
const freightLineMatch = rawText.match(/^[ \t]*(?:Freight|Shipping(?:[ \t]*(?:&|and)[ \t]*Handling)?|Delivery[ \t]+(?:Fee|Charge))(?![ \t]*(?:Method|Address|To|Date|Via|Terms)\b)[^\r\n]*?(?:\$([0-9][0-9,]*(?:\.[0-9]{1,2})?)|([0-9][0-9,]*\.[0-9]{2}))[ \t]*$/im);
const rawFreightStr = freightLineMatch ? (freightLineMatch[1] || freightLineMatch[2]) : '';

const invoiceLines = [];
const lineRegex = /^[ \t]*([A-Z0-9][A-Z0-9._/-]{1,})(?:[ \t]+.+?)?[ \t]+([0-9][0-9,]*)[ \t]+(?:\$([0-9][0-9,]*(?:\.[0-9]{1,4})?)|([0-9][0-9,]*\.[0-9]{2,4}))(?:[ \t]+\$?[0-9,]+(?:\.[0-9]{1,2})?)?[ \t]*$/gm;
let m;
while ((m = lineRegex.exec(rawText)) !== null) {
  const sku = m[1].trim();
  if (/^(?:PO-|INV-|INVOICE|DATE|TERMS|SUBTOTAL|TOTAL|TAX|FREIGHT|SHIPPING|HANDLING|DELIVERY|BALANCE|AMOUNT|PAGE)$/i.test(sku)) continue;
  const rawPrice = m[3] || m[4];
  invoiceLines.push({
    sku,
    billed_qty: Number(m[2].replace(/,/g, '')),
    billed_unit_cost_usd: Number(rawPrice.replace(/,/g, ''))
  });
}

if (invoiceLines.length === 0) {
  throw new Error('Could not extract structured SKU/quantity/price lines from PDF invoice text.');
}

const poLines = Array.isArray(item.po_lines) ? item.po_lines : [];
const receivingLines = Array.isArray(item.receiving_lines) ? item.receiving_lines : [];
if (poLines.length === 0) {
  throw new Error('Missing approved po_lines to match against PDF invoice ' + (invMatch ? invMatch[1] : '') + '.');
}

return [{
  json: {
    po_number: poMatch ? poMatch[1].trim() : 'PO-UNKNOWN',
    vendor: vendorMatch ? vendorMatch[1].trim() : (item.from?.value?.[0]?.name || 'Supplier'),
    invoice_number: invMatch ? invMatch[1].trim() : undefined,
    invoice_date: invDateMatch ? invDateMatch[1] : undefined,
    due_date: dueDateMatch ? dueDateMatch[1] : undefined,
    po_lines: poLines,
    receiving_lines: receivingLines,
    invoice_lines: invoiceLines,
    invoice_extra_fees_usd: rawFreightStr ? Number(rawFreightStr.replace(/,/g, '')) : 0,
    agreed_freight_cap_usd: typeof item.agreed_freight_cap_usd === 'number' ? item.agreed_freight_cap_usd : undefined
  }
}];

const raw = $input.first().json;
let envelope = raw;
if (typeof raw?.data === 'string' && raw.data.includes('data:')) {
  const dataLine = raw.data.split(/\r?\n/).find((l) => l.startsWith('data:'));
  if (dataLine) envelope = JSON.parse(dataLine.slice(5).trim());
}
const textPayload = envelope?.result?.content?.[0]?.text;
if (!textPayload) {
  throw new Error('Unexpected MCP response payload: ' + JSON.stringify(raw));
}
const audit = JSON.parse(textPayload);
if (!audit.ok) {
  throw new Error(audit.message || audit.error || 'PO Pilot 3-Way Match returned an error');
}
return [{ json: audit }];
